// Номер пина, к которому подключён светодиод
const int ledPin = 13; // Можно поменять на любой другой цифровой пин

void setup() {
  // Инициализируем этот пин как выход
  pinMode(ledPin, OUTPUT);
}

void loop() {
  // Включаем светодиод (подаём высокий уровень)
  digitalWrite(ledPin, HIGH);
  // Пауза — 1 секунда
  delay(1000);

  // Выключаем светодиод (подаём низкий уровень)
  digitalWrite(ledPin, LOW);
  // Пауза — 1 секунда
  delay(1000);
}
